import { DashContent, DashSection, DashPanel, DashMidRow } from '@atlantis/shared';
import type { TFunction } from '@atlantis/i18n';
import LivePulse from './LivePulse';
import ExperimentZone from './ExperimentZone';
import TodayInTech from './TodayInTech';
import AIRadar from './AIRadar';
import CommunityFeed from './CommunityFeed';
import PackageRadar from './PackageRadar';
import NpmTrends from './NpmTrends';
import TechArticles from './TechArticles';
import DevPulse from './DevPulse';

interface CategoryDetailProps {
  category: string;
  t: TFunction;
}

export function CategoryDetail({ category, t }: CategoryDetailProps) {
  return (
    <DashContent>
      {category === 'github' && (
        <>
          <DashSection id="live-pulse">
            <DashPanel>
              <LivePulse t={t} />
            </DashPanel>
          </DashSection>
          <DashSection id="experiment-zone">
            <DashPanel>
              <ExperimentZone t={t} />
            </DashPanel>
          </DashSection>
        </>
      )}

      {category === 'hackernews' && (
        <>
          <DashMidRow>
            <DashSection id="today-in-tech">
              <DashPanel style={{ height: '100%' }}>
                <TodayInTech t={t} />
              </DashPanel>
            </DashSection>
            <DashSection id="ai-radar">
              <DashPanel style={{ height: '100%' }}>
                <AIRadar t={t} />
              </DashPanel>
            </DashSection>
          </DashMidRow>
          <DashSection id="community-feed">
            <DashPanel>
              <CommunityFeed />
            </DashPanel>
          </DashSection>
        </>
      )}

      {category === 'packages' && (
        <>
          <DashSection id="package-radar">
            <DashPanel>
              <PackageRadar />
            </DashPanel>
          </DashSection>
          <DashSection id="npm-trends">
            <DashPanel>
              <NpmTrends t={t} />
            </DashPanel>
          </DashSection>
        </>
      )}

      {category === 'devcommunity' && (
        <>
          <DashSection id="tech-articles">
            <DashPanel>
              <TechArticles />
            </DashPanel>
          </DashSection>
          <DashSection id="dev-pulse">
            <DashPanel>
              <DevPulse />
            </DashPanel>
          </DashSection>
        </>
      )}
    </DashContent>
  );
}
