import { useState, useEffect, useCallback } from 'react';
import { putSetting, getSetting } from '@atlantis/shared';

// In-memory session cache — survives view switches, cleared on page reload
const sessionCache = new Map<string, { data: unknown; timestamp: number }>();
const CACHE_TTL = 3 * 60 * 1000; // 3 minutes

export function useFetch<T>(url: string, refreshMs = 5 * 60 * 1000) {
  const cached = sessionCache.get(url);
  const isFresh = cached && (Date.now() - cached.timestamp) < CACHE_TTL;

  const [data, setData] = useState<T | null>(isFresh ? (cached.data as T) : null);
  const [loading, setLoading] = useState(!isFresh);
  const [error, setError] = useState<string | null>(null);
  const [lastUpdated, setLastUpdated] = useState<Date | null>(
    isFresh ? new Date(cached.timestamp) : null
  );

  const fetchData = useCallback(async () => {
    try {
      const res = await fetch(url);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const json = await res.json();
      setData(json);
      setLastUpdated(new Date());
      setError(null);
      sessionCache.set(url, { data: json, timestamp: Date.now() });
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to fetch');
    } finally {
      setLoading(false);
    }
  }, [url]);

  useEffect(() => {
    // If we have fresh cached data, skip immediate fetch
    const entry = sessionCache.get(url);
    if (entry && (Date.now() - entry.timestamp) < CACHE_TTL) {
      setData(entry.data as T);
      setLastUpdated(new Date(entry.timestamp));
      setLoading(false);
    } else {
      fetchData();
    }
    const id = setInterval(fetchData, refreshMs);
    return () => clearInterval(id);
  }, [fetchData, refreshMs, url]);

  return { data, loading, error, lastUpdated, refresh: fetchData };
}

export function formatStars(n: number): string {
  if (n >= 1000) return `${(n / 1000).toFixed(1)}k`;
  return String(n);
}

export function formatNum(n: number): string {
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;
  if (n >= 1000) return `${(n / 1000).toFixed(1)}k`;
  return String(n);
}

export function timeAgo(dateStr: string): string {
  const ms = Date.now() - new Date(dateStr).getTime();
  const mins = Math.floor(ms / 60_000);
  if (mins < 1) return 'just now';
  if (mins < 60) return `${mins}m ago`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `${hours}h ago`;
  return `${Math.floor(hours / 24)}d ago`;
}

export function decodeHtml(html: string): string {
  const txt = document.createElement('textarea');
  txt.innerHTML = html;
  return txt.value;
}

export function nDaysAgo(n: number): string {
  const d = new Date();
  d.setDate(d.getDate() - n);
  return d.toISOString().split('T')[0];
}

export function getDomain(url: string | null | undefined): string {
  if (!url) return 'news.ycombinator.com';
  try {
    return new URL(url).hostname.replace(/^www\./, '');
  } catch {
    return '';
  }
}

export function usePanelCount(panelId: string): [number, (n: number) => void] {
  const [count, setCountState] = useState(0);
  const key = `ts:count:${panelId}`;

  useEffect(() => {
    getSetting(key).then((val) => {
      if (val) setCountState(Number(val));
    });
  }, [key]);

  const setCount = useCallback((n: number) => {
    setCountState(n);
    putSetting(key, String(n));
  }, [key]);

  return [count, setCount];
}
