import React from 'react';
import styled from '@emotion/styled';
import { MessageSquare, TrendingUp, ExternalLink } from 'lucide-react';
import { theme } from '@atlantis/shared';
import { localizedTimeAgo } from '@atlantis/i18n';
import type { TFunction } from '@atlantis/i18n';
import { useFetch, getDomain } from '../hooks';
import { SectionHeader } from './SectionHeader';

const ACCENT = '#58a6ff';

interface HNStory {
  objectID: string;
  title: string;
  url: string | null;
  author: string;
  points: number;
  num_comments: number;
  created_at: string;
}

interface HNResponse {
  hits: HNStory[];
}

const List = styled.div`
  display: flex;
  flex-direction: column;
  gap: 2px;
`;

const Item = styled.a`
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px ${theme.spacing.sm};
  border: 1px solid ${ACCENT}18;
  border-radius: ${theme.borderRadius.sm};
  background: linear-gradient(165deg, ${ACCENT}0b 0%, ${theme.colors.surface} 55%, ${theme.colors.surface} 100%);
  text-decoration: none;
  transition: background 0.2s, border-color 0.2s, transform 0.2s;

  &:hover {
    background: linear-gradient(165deg, ${ACCENT}14 0%, ${theme.colors.surfaceRaised} 55%, ${theme.colors.surfaceRaised} 100%);
    border-color: ${ACCENT}5c;
    transform: translateX(2px);
  }
`;

const ItemTitle = styled.div`
  font-size: ${theme.typography.fontSizeBase};
  color: ${theme.colors.mainText};
  line-height: 1.4;
  display: flex;
  align-items: flex-start;
  gap: 6px;
`;

const LinkIcon = styled.span`
  color: ${theme.colors.mainTextMuted};
  flex-shrink: 0;
  margin-top: 2px;
`;

const ItemMeta = styled.div`
  display: flex;
  align-items: center;
  gap: ${theme.spacing.sm};
  font-size: 12px;
  color: ${theme.colors.mainTextMuted};
  font-family: ${theme.typography.fontFamilyMono};
`;

const Score = styled.span`
  display: flex;
  align-items: center;
  gap: 3px;
  color: ${ACCENT};
  font-weight: 600;
`;

const Comments = styled.span`
  display: flex;
  align-items: center;
  gap: 3px;
`;

const Domain = styled.span`
  color: ${theme.colors.mainTextMuted};
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
`;

const EmptyState = styled.div`
  padding: ${theme.spacing.xl};
  color: ${theme.colors.mainTextMuted};
  font-size: ${theme.typography.fontSizeSm};
  text-align: center;
`;

const Divider = styled.div`
  height: 1px;
  background: ${ACCENT}2a;
  margin: 2px 0;
`;

interface AIRadarProps {
  t: TFunction;
}

export default function AIRadar({ t }: AIRadarProps) {
  const since = Math.floor((Date.now() - 48 * 60 * 60 * 1000) / 1000);
  const url = `https://hn.algolia.com/api/v1/search?query=AI+LLM+model+open+source&tags=story&hitsPerPage=8&numericFilters=created_at_i>${since}`;
  const { data, loading, lastUpdated, refresh } = useFetch<HNResponse>(url);

  const stories = data?.hits ?? [];

  return (
    <div>
      <SectionHeader
        title={t('nav.aiRadar')}
        color={ACCENT}
        lastUpdated={lastUpdated}
        loading={loading}
        onRefresh={refresh}
        t={t}
      />
      {!stories.length ? (
        <EmptyState>{loading ? t('aiRadar.loading') : t('aiRadar.empty')}</EmptyState>
      ) : (
        <List>
          {stories.map((story, i) => {
            const href = story.url ?? `https://news.ycombinator.com/item?id=${story.objectID}`;
            return (
              <React.Fragment key={story.objectID}>
                {i > 0 && <Divider />}
                <Item href={href} target="_blank" rel="noopener noreferrer">
                  <ItemTitle>
                    <LinkIcon><ExternalLink size={12} /></LinkIcon>
                    {story.title}
                  </ItemTitle>
                  <ItemMeta>
                    <Score><TrendingUp size={11} />{story.points ?? 0}</Score>
                    <Comments><MessageSquare size={11} />{story.num_comments ?? 0}</Comments>
                    <Domain>{getDomain(story.url)}</Domain>
                    <span style={{ marginLeft: 'auto' }}>{localizedTimeAgo(story.created_at, t)}</span>
                  </ItemMeta>
                </Item>
              </React.Fragment>
            );
          })}
        </List>
      )}
    </div>
  );
}
