export default function JournalPage({ onNavigate, t }: JournalPageProps) {
  const ghUrl = `https://api.github.com/search/repositories?q=created:>${nDaysAgo(7)}&sort=stars&order=desc&per_page=1`;
  const hnUrl = 'https://hn.algolia.com/api/v1/search?tags=front_page&hitsPerPage=6';
  const { data: ghData } = useFetch<GHResponse>(ghUrl);
  const { data: hnData } = useFetch<HNResponse>(hnUrl);

  const heroRepo = ghData?.items?.[0] ?? null;
  const topStories = hnData?.hits ?? [];

  const [counts, setCounts] = useState<Record<string, number>>({});

  useEffect(() => {
    const keys = [
      'live-pulse', 'experiment-zone', 'today-in-tech', 'ai-radar',
      'community-feed', 'package-radar', 'npm-trends', 'tech-articles', 'dev-pulse',
    ];
    Promise.all(keys.map((k) => getSetting(`ts:count:${k}`).then((v) => [k, Number(v ?? 0)] as const)))
      .then((pairs) => setCounts(Object.fromEntries(pairs)));
  }, []);

  const getCategoryCount = (panels: readonly string[]) =>
    panels.reduce((sum, p) => sum + (counts[p] ?? 0), 0);

  const graphBars: GraphBar[] = CATEGORIES.map((cat) => ({
    label: cat.label,
    value: getCategoryCount(cat.panels),
    color: cat.color,
  }));

  const today = new Date().toLocaleDateString('en-US', {
    weekday: 'long',
    year: 'numeric',
    month: 'long',
    day: 'numeric',
  });

  const totalFeeds = CATEGORIES.reduce((s, c) => s + c.panels.length, 0);
  const hasActivityData = graphBars.some((b) => b.value > 0);

  return (
    <Page>
      {/* ── MASTHEAD ── */}
      <Masthead>
        <MastheadEdition>{t('journal.title')}</MastheadEdition>
        <MastheadTitle>TechScope</MastheadTitle>
        <MastheadRule />
        <MastheadMeta>
          <span>{today}</span>
          <span>&middot;</span>
          <LiveBadge>
            <LiveDot />
            {t('journal.live')} &mdash; {totalFeeds} {t('journal.feedsActive')}
          </LiveBadge>
        </MastheadMeta>
      </Masthead>

      {/* ── HERO: repo + stories ── */}
      <Section delay={1}>
        <HeroGrid>
          {/* GitHub Headline */}
          <div>
            <SectionHead>
              <SectionDot color="#3fb950" />
              <SectionTitle color="#3fb950">{t('journal.headline')}</SectionTitle>
              <SectionRule />
            </SectionHead>
            {heroRepo ? (
              <HeroCard href={heroRepo.html_url} target="_blank" rel="noopener noreferrer">
                <HeroLabel><Zap size={10} /> Trending this week</HeroLabel>
                <HeroRepoName>{heroRepo.full_name}</HeroRepoName>
                <HeroDesc>{heroRepo.description ?? t('noDescription')}</HeroDesc>
                <HeroFooter>
                  <HeroStars><Star size={12} />{formatStars(heroRepo.stargazers_count)}</HeroStars>
                  {heroRepo.language && <HeroLang>{heroRepo.language}</HeroLang>}
                  <ExternalLink size={10} style={{ marginLeft: 'auto', opacity: 0.4 }} />
                </HeroFooter>
              </HeroCard>
            ) : (
              <EmptyHero>{t('livePulse.loading')}</EmptyHero>
            )}
          </div>

          <ColumnDivider />

          {/* HN Top Stories */}
          <StoriesColumn>
            <SectionHead>
              <SectionDot color="#ff6600" />
              <SectionTitle color="#ff6600">{t('journal.topStories')}</SectionTitle>
              <SectionRule />
            </SectionHead>
            {topStories.length > 0 ? (
              topStories.map((story, i) => {
                const href = story.url ?? `https://news.ycombinator.com/item?id=${story.objectID}`;
                return (
                  <StoryItem key={story.objectID} index={i} href={href} target="_blank" rel="noopener noreferrer">
                    <StoryRank>{i + 1}</StoryRank>
                    <StoryContent>
                      <StoryTitle>{story.title}</StoryTitle>
                      <StoryMeta>
                        <span style={{ color: '#ff6600', fontWeight: 600 }}>{story.points ?? 0} pts</span>
                        <span>{story.num_comments ?? 0} comments</span>
                        <span style={{ opacity: 0.5 }}>{getDomain(story.url)}</span>
                      </StoryMeta>
                    </StoryContent>
                  </StoryItem>
                );
              })
            ) : (
              <EmptyHero>{t('todayInTech.loading')}</EmptyHero>
            )}
          </StoriesColumn>
        </HeroGrid>
      </Section>

      <ThinRule />

      {/* ── CATEGORY CARDS ── */}
      <Section delay={2}>
        <SectionHead>
          <SectionDot color={theme.colors.accent} />
          <SectionTitle>{t('journal.categories')}</SectionTitle>
          <SectionRule />
        </SectionHead>
        <CatGrid>
          {CATEGORIES.map((cat) => {
            const count = getCategoryCount(cat.panels);
            return (
              <CatCard key={cat.id} accentColor={cat.color} onClick={() => onNavigate(cat.id)}>
                <CatHeader>
                  <CatTitle>{cat.label}</CatTitle>
                  <CatCount color={cat.color}>{count || ''}</CatCount>
                </CatHeader>
                <CatDesc>{cat.desc}</CatDesc>
                <CatFooter color={cat.color}>
                  {cat.panels.length} feeds <ChevronRight size={12} />
                </CatFooter>
              </CatCard>
            );
          })}
        </CatGrid>
      </Section>

      {/* ── ACTIVITY GRAPH — only shown when there's data ── */}
      {hasActivityData && (
        <>
          <ThinRule />
          <Section delay={3}>
            <SectionHead>
              <SectionDot color={theme.colors.accent} />
              <SectionTitle>{t('journal.activity')}</SectionTitle>
              <SectionRule />
            </SectionHead>
            <GraphWrap>
              <CategoryGraph bars={graphBars} />
            </GraphWrap>
          </Section>
        </>
      )}
    </Page>
  );
}
